        Adds a specified quantity of an item to the inventory.
        """
        if item_id in self._stock:
            self._stock[item_id] += quantity
        else:
            self._stock[item_id] = quantity

    def remove_stock(self, item_id, quantity):
        """
        Removes a specified quantity of an item from the inventory.
        If the quantity exceeds the available stock, the item is removed entirely.
        """
        if item_id in self._stock:
            if self._stock[item_id] >= quantity:
                self._stock[item_id] -= quantity
                if self._stock[item_id] == 0:
