        if quantity < 0:
            raise ValueError("Quantity must be non-negative.")
        if item_id in self._stock_q:
            self._stock_q[item_id] += quantity
        else:
            self._stock_q[item_id] = quantity

    def __n_remove_stock(self, item_id: str, quantity: int):
        if quantity < 0:
            raise ValueError("Quantity must be non-negative.")
        if item_id not in self._stock_q or self._stock_q[item_id] < quantity:
            raise ValueError("Insufficient stock.")
        self._stock_q[item_id] -= quantity
        if self._stock_q[item_id] == 0:
            del self._stock_q[item_id]

